export const styles = stylex.create({
  // A `null` declares nothing, and the property stays in the style object
  // carrying no class name -- which is what unsets an earlier declaration of
  // the same property on merge. `backgroundColor: 'red'` is here so the verdict
  // reads a real declaration beside the absent ones.
  longhand: { color: null, backgroundColor: 'red' },
  array: { color: [null] },
  arrayOfNulls: { color: [null, null, null] },
  emptyArray: { color: [] },
  leading: { color: [null, 'red'] },
  trailing: { color: ['red', null] },
  betweenVars: { color: ['var(--a)', null, 'var(--b)'] },
  conditionDefault: { color: { default: null, ':hover': 'red' } },
  conditionBranch: { color: { default: 'red', ':hover': null } },
  everyBranch: { color: { default: null, ':hover': null, '@media print': null } },
  insidePseudo: { ':hover': { color: null } },
  customProperty: { '--x': null, '--y': 'red' },
  vendorPrefixed: { WebkitLineClamp: null },
  numeric: { zIndex: null },
  content: { content: null },
  neighbours: { backgroundColor: 'blue', color: [null], borderColor: 'green' },
});

import * as stylex from '@stylexjs/stylex';

// Under the default `property-specificity` resolution `borderTop` is refused as
// a property, so a `null` on it leaves no key at all. `margin` is not refused
// and has no expansion there, so it keeps its own. Both answers are about the
// property table rather than about the value, and the expansion is what decides
// how many keys an absence lands on.
export const styles = stylex.create({
  refusedShorthand: { borderTop: null },
  refusedShorthandArray: { borderTop: [null] },
  unexpandedShorthand: { margin: null },
  unexpandedShorthandArray: { margin: [null] },
  survivor: { color: 'red' },
});

import * as stylex from '@stylexjs/stylex';

// `keyframes`, `positionTry` and `viewTransitionClass` validate no values, so a
// boolean is dropped there rather than refused -- unlike inside `create`, which
// the entry beside this one asks about.
export const fade = stylex.keyframes({
  from: { opacity: false, color: null },
  to: { opacity: 1 },
});

export const fallback = stylex.positionTry({
  positionAnchor: '--anchor',
  top: false,
  left: null,
});

export const transition = stylex.viewTransitionClass({
  group: { color: null, opacity: false },
  old: { animationName: 'fade' },
});

